}

Method.Source:
/// <summary>
/// This method inserts product onhand with catch weight fields
/// </summary>
/// <param name = "inventOnhandStorageReportLine">METInventOnhandReportLines_Extension</param>
/// <param name = "_inventSum">InventSum</param>
/// <param name = "_inventDim">InventDim</param>
public void insertProductOnhand(InventOnhandStorageReportLine inventOnhandStorageReportLine, InventSum _inventSum, InventDim _inventDim)
{
    inventOnhandStorageReportLine.METPhysicalInvent = _inventSum.PhysicalInvent;
    inventOnhandStorageReportLine.METPdsCWPhysicalInvent = _inventSum.PdsCWPhysicalInvent;
    next insertProductOnhand(inventOnhandStorageReportLine, _inventSum, _inventDim);        
}

/// <summary>
/// This method inserts CW product onhand with catch weight fields
/// </summary>
/// <param name = "inventOnhandStorageReportLine">InventOnhandStorageReportLine</param>
/// <param name = "_inventSum">InventSum</param>
/// <param name = "_inventDim">InventDim</param>
public void insertCWProductOnhand(InventOnhandStorageReportLine inventOnhandStorageReportLine, InventSum _inventSum, InventDim _inventDim)
{
    inventOnhandStorageReportLine.METPhysicalInvent = _inventSum.PhysicalInvent;
    inventOnhandStorageReportLine.METPdsCWPhysicalInvent = _inventSum.PdsCWPhysicalInvent;
    next insertCWProductOnhand(inventOnhandStorageReportLine, _inventSum, _inventDim);
}
